with src as (
 select * from jsonb_to_recordset($qa_batch11$
[
{"name":"experiment","aliases":["experiment Fetish Techno Tokyo October 2026","experiment B.A.R.K. White Space Lab"],"city":"tokyo","date":"2026-10-16","start_date":"2026-10-16","end_date":"2026-10-16","description":"experiment distils Shibuya into a dark, precise collision of fetish aesthetics and relentless techno: body, sound and desire given enough room to become their own language.","link":"https://experiment-re-cords.jp/en/next-event/","ticket_url":"https://experiment-re-cords.jp/en/next-event/","location":"White Space Lab, Shibuya, Tokyo, Japan","lat":35.6595,"lng":139.6989,"vibe":"inclusive Shibuya fetish-techno laboratory with black-clad precision and body-forward sound","intel":{"hours":"19:00–23:30 Friday 16 October 2026; changing access is available 18:30–19:00.","entry_wait":"Guest-list registration gives ¥500 off; register in advance and expect entry to be refused if the strongly encouraged dress code is ignored.","best_arrival":"Use the early changing window if you need it, then be in by 19:00 for a cleaner entry and the complete short-form techno arc.","crowd_mix":"Fetish-techno regulars, queer-friendly Shibuya clubbers, fashion-minded dancers and people who prefer intent over generic nightlife.","dress_code":"Fetish styling is strongly encouraged; all black is the safe default. No re-entry, lockers or cloakroom are available.","host_inclusivity":"experiment calls itself raw, underground and inclusive, and asks guests to report inappropriate behaviour to crew immediately.","lineup":"B.A.R.K., Hexe, Znthiia, Ai and Louis Kordexe; Yousuke Fuyama is also listed in the live RA programme.","age_limit":"Confirm with organiser before attending.","source_urls":["https://experiment-re-cords.jp/en/next-event/","https://experiment-re-cords.jp/en/home/"],"research_status":"official_date_hours_host_policy_dress_code_and_venue_area_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Casket of Horrors: Kabukicho in Space","aliases":["Haus von Schwarz Casket of Horrors Tokyo 2026","Kabukicho in Space 666th anniversary"],"city":"tokyo","date":"2026-10-17","start_date":"2026-10-17","end_date":"2026-10-17","description":"Haus von Schwarz throws its Casket of Horrors into orbit: Tokyo alternative drag, burlesque and queer art for anyone who prefers their Halloween ridiculous, theatrical and a little extraterrestrial.","link":"https://kabukichoinspace.peatix.com/","ticket_url":"https://kabukichoinspace.peatix.com/","location":"Shinjuku Heist, Horizon Building B2F, 2-25-6 Kabukicho, Shinjuku, Tokyo, Japan","lat":35.6967,"lng":139.7047,"vibe":"alternative queer cabaret from outer space: dark drag, burlesque and Tokyo underground theatre","intel":{"hours":"19:00–22:00 Saturday 17 October 2026.","entry_wait":"Advance tickets are ¥4,000 and door tickets ¥5,000, plus a ¥700 drink ticket at entry; secure advance access for the smaller performance format.","best_arrival":"Arrive for 19:00 so the space-themed drag narrative lands as a whole rather than as isolated late acts.","crowd_mix":"Alternative drag followers, burlesque fans, local queer creatives, costume-minded visitors and audiences that value performance over a conventional club set.","dress_code":"No mandatory look is stated; dark theatrical or space-age styling fits the 666th-anniversary concept without being required.","host_inclusivity":"Haus von Schwarz’s programme is built around Tokyo’s alternative and queer art community, foregrounding emerging performers alongside established local acts.","lineup":"Alternative drag, burlesque, live musicians and special guest/debut performances; the final artist roster is released by the house.","age_limit":"Confirm with ticketing before attending.","source_urls":["https://www.timeout.com/tokyo/lgbtq/haus-von-schwarz-presents-casket-of-horrors-kabukicho-in-space","https://kabukichoinspace.peatix.com/"],"research_status":"published_date_hours_full_ad